1	import { useNavigate } from "react-router-dom";
2	import { useAuth } from "@/hooks/useAuth";
3	import AppHeader from "@/components/AppHeader";
4	import JobSidebar from "@/components/JobSidebar";
5	import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
6	
7	/**
8	 * Shared layout with persistent JobSidebar + AppHeader.
9	 * Used by all authenticated pages (Settings, Billing, Admin, etc.).
10	 */
11	const SidebarLayout = ({ children }: { children: React.ReactNode }) => {
12	  const { user } = useAuth();
13	  const navigate = useNavigate();
14	
15	  return (
16	    <SidebarProvider className="h-svh overflow-hidden">
17	      <JobSidebar
18	        selectedJobId={null}
19	        showDashboard={false}
20	        showMyJobs={false}
21	        onNewJob={() => navigate("/?new=1")}
22	        onDashboard={() => navigate("/")}
23	        onMyJobs={() => navigate("/jobs")}
24	        onAuthRequired={() => navigate("/auth")}
25	        isAuthenticated={!!user}
26	      />
27	      <SidebarInset className="h-svh overflow-y-auto">
28	        <AppHeader />
29	        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
30	          <SidebarTrigger />
31	        </div>
32	        {children}
33	      </SidebarInset>
34	    </SidebarProvider>
35	  );
36	};
37	
38	export default SidebarLayout;
